-- ────────────────────────────────────────────────────────────
-- AI COACH ASSISTANT
-- Training session plans generated by AI with coach editing,
-- approval workflow, version history, post-session reports and
-- individual player development plans.
--
-- Security model (mirrors the existing coaching conventions):
--   * "admin"   → academy owner/admins (profiles.role = 'admin')
--   * "coach"   → a member with a linked staff record
--                 (public.coaches.profile_id = auth.uid())
--   * coaches see only plans they created or plans for the teams
--     they are assigned to (teams.coach_id → coaches.id).
-- All mutations run through SECURITY DEFINER RPCs that re-check
-- access in SQL; direct client writes are not allowed.
-- ────────────────────────────────────────────────────────────

-- ── 1. ACCESS HELPERS ───────────────────────────────────────

-- Current academy admin (owner) for the authenticated user.
CREATE OR REPLACE FUNCTION public.is_academy_admin()
RETURNS BOOLEAN
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = auth.uid()
      AND p.role = 'admin'
      AND p.academy_id = public.current_academy_id()
  );
$$;
GRANT EXECUTE ON FUNCTION public.is_academy_admin() TO authenticated;

-- The authenticated user is linked to a staff coach record in the academy
-- (they accepted a coach invitation → public.coaches.profile_id set).
CREATE OR REPLACE FUNCTION public.is_academy_coach()
RETURNS BOOLEAN
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.coaches c
    WHERE c.profile_id = auth.uid()
      AND c.is_active
      AND c.academy_id = public.current_academy_id()
  );
$$;
GRANT EXECUTE ON FUNCTION public.is_academy_coach() TO authenticated;

-- Academy staff = admin OR linked coach.
CREATE OR REPLACE FUNCTION public.is_academy_staff()
RETURNS BOOLEAN
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT public.is_academy_admin() OR public.is_academy_coach();
$$;
GRANT EXECUTE ON FUNCTION public.is_academy_staff() TO authenticated;

-- Colleges (coaches.id) of the current user within the academy.
CREATE OR REPLACE FUNCTION public.current_coach_ids()
RETURNS UUID[]
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT ARRAY(
    SELECT c.id FROM public.coaches c
    WHERE c.profile_id = auth.uid()
      AND c.is_active
      AND c.academy_id = public.current_academy_id()
  );
$$;
GRANT EXECUTE ON FUNCTION public.current_coach_ids() TO authenticated;

-- Team ids the current coach is assigned to.
CREATE OR REPLACE FUNCTION public.current_coach_team_ids()
RETURNS UUID[]
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT ARRAY(
    SELECT t.id FROM public.teams t
    WHERE t.academy_id = public.current_academy_id()
      AND t.coach_id = ANY (public.current_coach_ids())
  );
$$;
GRANT EXECUTE ON FUNCTION public.current_coach_team_ids() TO authenticated;

-- Member ids on the current coach's assigned teams.
CREATE OR REPLACE FUNCTION public.current_coach_player_ids()
RETURNS UUID[]
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT ARRAY(
    SELECT tm.member_id FROM public.team_members tm
    WHERE tm.team_id = ANY (public.current_coach_team_ids())
  );
$$;
GRANT EXECUTE ON FUNCTION public.current_coach_player_ids() TO authenticated;

-- ── 2. AI TRAINING PLANS ────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.ai_training_plans (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  academy_id UUID NOT NULL REFERENCES public.academies(id) ON DELETE CASCADE
    DEFAULT public.current_academy_id(),
  branch_id UUID REFERENCES public.academy_branches(id) ON DELETE SET NULL,
  team_id UUID REFERENCES public.teams(id) ON DELETE SET NULL,
  -- Training session the plan is assigned to (optional convenience link).
  session_id UUID REFERENCES public.training_sessions(id) ON DELETE SET NULL,
  sport_id UUID REFERENCES public.sports(id) ON DELETE SET NULL,
  sport TEXT,
  title TEXT NOT NULL CHECK (btrim(title) <> ''),
  main_objective TEXT,
  secondary_objectives JSONB NOT NULL DEFAULT '[]',
  skill_focus JSONB NOT NULL DEFAULT '[]',
  intensity_theme TEXT NOT NULL DEFAULT 'moderate'
    CHECK (intensity_theme IN ('light', 'moderate', 'intense')),
  session_duration_min INTEGER NOT NULL DEFAULT 60 CHECK (session_duration_min BETWEEN 1 AND 480),
  num_players INTEGER NOT NULL DEFAULT 0 CHECK (num_players >= 0),
  num_coaches INTEGER NOT NULL DEFAULT 1 CHECK (num_coaches >= 0),
  age_group TEXT,
  skill_level TEXT
    CHECK (skill_level IS NULL OR skill_level IN ('beginner', 'intermediate', 'advanced')),
  gender TEXT CHECK (gender IS NULL OR gender IN ('male', 'female', 'mixed', 'all')),
  equipment JSONB NOT NULL DEFAULT '[]',
  space TEXT,
  notes TEXT,
  status TEXT NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft', 'submitted', 'approved', 'rejected', 'archived')),
  approval_note TEXT,
  is_favorite BOOLEAN NOT NULL DEFAULT FALSE,
  is_template BOOLEAN NOT NULL DEFAULT FALSE,
  template_name TEXT,
  -- AI generation provenance.
  ai_provider TEXT,
  ai_model TEXT,
  ai_generation_id TEXT,
  ai_estimated_cost NUMERIC(12, 6) NOT NULL DEFAULT 0,
  version INTEGER NOT NULL DEFAULT 1,
  approved_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  approved_at TIMESTAMPTZ,
  created_by UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  updated_by UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_ai_plans_academy
  ON public.ai_training_plans(academy_id, status, updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_ai_plans_team
  ON public.ai_training_plans(team_id);
CREATE INDEX IF NOT EXISTS idx_ai_plans_creator
  ON public.ai_training_plans(created_by);

-- Sections of a plan (e.g. warm-up, technical, tactical, fitness, evaluation).
CREATE TABLE IF NOT EXISTS public.ai_training_plan_sections (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  plan_id UUID NOT NULL REFERENCES public.ai_training_plans(id) ON DELETE CASCADE,
  section_type TEXT NOT NULL
    CHECK (section_type IN ('warmup', 'technical', 'tactical', 'fitness', 'evaluation', 'cooldown')),
  title TEXT NOT NULL,
  purpose TEXT,
  duration_min INTEGER NOT NULL CHECK (duration_min > 0),
  -- Skill focus tags for this section's exercises (drill-book mapping).
  skill_focus JSONB NOT NULL DEFAULT '[]',
  order_index INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_ai_sections_plan
  ON public.ai_training_plan_sections(plan_id, order_index);

-- Exercises inside a section.
CREATE TABLE IF NOT EXISTS public.training_exercises (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  section_id UUID NOT NULL REFERENCES public.ai_training_plan_sections(id) ON DELETE CASCADE,
  name TEXT NOT NULL CHECK (btrim(name) <> ''),
  purpose TEXT,
  duration_min INTEGER NOT NULL CHECK (duration_min > 0),
  num_players INTEGER,
  equipment JSONB NOT NULL DEFAULT '[]',
  setup TEXT,
  instructions JSONB NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(instructions) = 'array'),
  coaching_points JSONB NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(coaching_points) = 'array'),
  difficulty TEXT CHECK (difficulty IS NULL OR difficulty IN ('easy', 'medium', 'hard')),
  order_index INTEGER NOT NULL DEFAULT 0,
  ai_generated BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_training_exercises_section
  ON public.training_exercises(section_id, order_index);

-- Version history (full snapshot per version, enabling revert).
CREATE TABLE IF NOT EXISTS public.training_plan_versions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  plan_id UUID NOT NULL REFERENCES public.ai_training_plans(id) ON DELETE CASCADE,
  version INTEGER NOT NULL CHECK (version > 0),
  editor_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  action TEXT NOT NULL
    CHECK (action IN ('created', 'generated', 'edited', 'submitted', 'approved',
                      'rejected', 'restored', 'archived')),
  snapshot JSONB NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (plan_id, version)
);
CREATE INDEX IF NOT EXISTS idx_ai_versions_plan
  ON public.training_plan_versions(plan_id, version DESC);

-- Linking plans to concrete training sessions.
CREATE TABLE IF NOT EXISTS public.training_plan_assignments (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  plan_id UUID NOT NULL REFERENCES public.ai_training_plans(id) ON DELETE CASCADE,
  session_id UUID NOT NULL REFERENCES public.training_sessions(id) ON DELETE CASCADE,
  scheduled_at TIMESTAMPTZ,
  notes TEXT,
  assigned_by UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (plan_id, session_id)
);
CREATE INDEX IF NOT EXISTS idx_ai_assignments_plan
  ON public.training_plan_assignments(plan_id);
CREATE INDEX IF NOT EXISTS idx_ai_assignments_session
  ON public.training_plan_assignments(session_id);

-- Post-session reports: planned vs actual, ratings, injuries, notes.
CREATE TABLE IF NOT EXISTS public.post_session_reports (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  academy_id UUID NOT NULL REFERENCES public.academies(id) ON DELETE CASCADE
    DEFAULT public.current_academy_id(),
  plan_id UUID REFERENCES public.ai_training_plans(id) ON DELETE SET NULL,
  session_id UUID REFERENCES public.training_sessions(id) ON DELETE SET NULL,
  team_id UUID REFERENCES public.teams(id) ON DELETE SET NULL,
  coach_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  completed BOOLEAN NOT NULL DEFAULT TRUE,
  actual_duration_min INTEGER,
  -- [{exercise_id, name, planned_duration, actual_duration, completed, notes}]
  exercises_performance JSONB NOT NULL DEFAULT '[]',
  performance_rating INTEGER CHECK (performance_rating BETWEEN 1 AND 5),
  intensity_rating INTEGER CHECK (intensity_rating BETWEEN 1 AND 5),
  engagement_rating INTEGER CHECK (engagement_rating BETWEEN 1 AND 5),
  skills_improved JSONB NOT NULL DEFAULT '[]',
  skills_need_work JSONB NOT NULL DEFAULT '[]',
  injuries JSONB NOT NULL DEFAULT '[]',
  notes TEXT,
  player_notes JSONB NOT NULL DEFAULT '[]',
  created_by UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (plan_id, session_id)
);
CREATE INDEX IF NOT EXISTS idx_psr_academy
  ON public.post_session_reports(academy_id, updated_at DESC);

-- Individual player development plans.
CREATE TABLE IF NOT EXISTS public.player_development_plans (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  academy_id UUID NOT NULL REFERENCES public.academies(id) ON DELETE CASCADE
    DEFAULT public.current_academy_id(),
  player_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  coach_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  sport TEXT,
  position TEXT,
  strengths JSONB NOT NULL DEFAULT '[]',
  areas_to_improve JSONB NOT NULL DEFAULT '[]',
  short_term_goals JSONB NOT NULL DEFAULT '[]',
  long_term_goals JSONB NOT NULL DEFAULT '[]',
  recommended_drills JSONB NOT NULL DEFAULT '[]',
  weekly_focus TEXT,
  progress_checkpoints JSONB NOT NULL DEFAULT '[]',
  review_date DATE,
  -- Visibility: 'coach' (private) < 'academy' < 'player' < 'parent'.
  visibility TEXT NOT NULL DEFAULT 'coach'
    CHECK (visibility IN ('coach', 'academy', 'player', 'parent')),
  -- Coach-only notes; never exposed below the 'coach' visibility tier.
  private_notes TEXT,
  status TEXT NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft', 'approved', 'archived')),
  approved_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  approved_at TIMESTAMPTZ,
  created_by UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_pdp_player
  ON public.player_development_plans(player_id);
CREATE INDEX IF NOT EXISTS idx_pdp_academy
  ON public.player_development_plans(academy_id);

-- Goals under a development plan.
CREATE TABLE IF NOT EXISTS public.player_development_goals (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  plan_id UUID NOT NULL REFERENCES public.player_development_plans(id) ON DELETE CASCADE,
  title TEXT NOT NULL CHECK (btrim(title) <> ''),
  goal_type TEXT NOT NULL CHECK (goal_type IN ('short_term', 'long_term')),
  target_date DATE,
  progress INTEGER NOT NULL DEFAULT 0 CHECK (progress BETWEEN 0 AND 100),
  achieved BOOLEAN NOT NULL DEFAULT FALSE,
  notes TEXT,
  order_index INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_pdp_goals_plan
  ON public.player_development_goals(plan_id);

-- AI usage accounting (tokens / cost / latency per generation).
CREATE TABLE IF NOT EXISTS public.ai_usage_log (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  academy_id UUID NOT NULL REFERENCES public.academies(id) ON DELETE CASCADE
    DEFAULT public.current_academy_id(),
  user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  feature TEXT NOT NULL,
  provider TEXT,
  model TEXT,
  prompt_tokens INTEGER NOT NULL DEFAULT 0,
  completion_tokens INTEGER NOT NULL DEFAULT 0,
  estimated_cost NUMERIC(12, 6) NOT NULL DEFAULT 0,
  latency_ms INTEGER NOT NULL DEFAULT 0,
  success BOOLEAN NOT NULL DEFAULT TRUE,
  error TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_ai_usage_academy
  ON public.ai_usage_log(academy_id, created_at);

-- ── 3. ROW LEVEL SECURITY ───────────────────────────────────

ALTER TABLE public.ai_training_plans ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ai_training_plan_sections ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.training_exercises ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.training_plan_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.training_plan_assignments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.post_session_reports ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.player_development_plans ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.player_development_goals ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ai_usage_log ENABLE ROW LEVEL SECURITY;

-- Plans: staff of the academy can read plans they own, plans for teams they
-- coach, and academy templates. Non-staff members see nothing.
DROP POLICY IF EXISTS "AI plans read staff" ON public.ai_training_plans;
CREATE POLICY "AI plans read staff" ON public.ai_training_plans
  FOR SELECT TO authenticated USING (
    academy_id = public.current_academy_id()
    AND public.is_academy_staff()
    AND (
      public.is_academy_admin()
      OR created_by = auth.uid()
      OR (team_id IS NULL AND NOT is_template)
      OR team_id = ANY (public.current_coach_team_ids())
      OR is_template = TRUE
    )
  );

DROP POLICY IF EXISTS "AI plans read coach teams" ON public.ai_training_plans;
CREATE POLICY "AI plans read coach teams" ON public.ai_training_plans
  FOR SELECT TO authenticated USING (
    academy_id = public.current_academy_id()
    AND public.is_academy_coach()
    AND (
      team_id = ANY (public.current_coach_team_ids())
      OR created_by = auth.uid()
      OR team_id IS NULL
    )
  );

-- Sections & exercises are read through their parent plan.
DROP POLICY IF EXISTS "AI sections read" ON public.ai_training_plan_sections;
CREATE POLICY "AI sections read" ON public.ai_training_plan_sections
  FOR SELECT TO authenticated USING (
    EXISTS (
      SELECT 1 FROM public.ai_training_plans p
      WHERE p.id = plan_id
        AND p.academy_id = public.current_academy_id()
        AND public.is_academy_staff()
        AND (
          public.is_academy_admin()
          OR p.created_by = auth.uid()
          OR (p.team_id IS NULL AND NOT p.is_template)
          OR p.team_id = ANY (public.current_coach_team_ids())
          OR p.is_template = TRUE
        )
    )
  );

DROP POLICY IF EXISTS "AI exercises read" ON public.training_exercises;
CREATE POLICY "AI exercises read" ON public.training_exercises
  FOR SELECT TO authenticated USING (
    EXISTS (
      SELECT 1 FROM public.ai_training_plan_sections s
      WHERE s.id = section_id
        AND EXISTS (
          SELECT 1 FROM public.ai_training_plans p
          WHERE p.id = s.plan_id
            AND p.academy_id = public.current_academy_id()
            AND public.is_academy_staff()
            AND (
              public.is_academy_admin()
              OR p.created_by = auth.uid()
              OR (p.team_id IS NULL AND NOT p.is_template)
              OR p.team_id = ANY (public.current_coach_team_ids())
              OR p.is_template = TRUE
            )
        )
    )
  );

-- Versions: read for plans the staff may read.
DROP POLICY IF EXISTS "AI versions read" ON public.training_plan_versions;
CREATE POLICY "AI versions read" ON public.training_plan_versions
  FOR SELECT TO authenticated USING (
    EXISTS (
      SELECT 1 FROM public.ai_training_plans p
      WHERE p.id = plan_id
        AND p.academy_id = public.current_academy_id()
        AND public.is_academy_staff()
        AND (
          public.is_academy_admin()
          OR p.created_by = auth.uid()
          OR p.team_id = ANY (public.current_coach_team_ids())
          OR p.is_template = TRUE
        )
    )
  );

-- Assignments: read when the plan is readable.
DROP POLICY IF EXISTS "AI assignments read" ON public.training_plan_assignments;
CREATE POLICY "AI assignments read" ON public.training_plan_assignments
  FOR SELECT TO authenticated USING (
    EXISTS (
      SELECT 1 FROM public.ai_training_plans p
      WHERE p.id = plan_id
        AND p.academy_id = public.current_academy_id()
        AND public.is_academy_staff()
    )
  );

-- Post-session reports: staff read within the academy.
DROP POLICY IF EXISTS "PSR read staff" ON public.post_session_reports;
CREATE POLICY "PSR read staff" ON public.post_session_reports
  FOR SELECT TO authenticated USING (
    academy_id = public.current_academy_id()
    AND public.is_academy_staff()
  );

-- Development plans: admins & coaches read plan players they manage.
DROP POLICY IF EXISTS "PDP read admin" ON public.player_development_plans;
CREATE POLICY "PDP read admin" ON public.player_development_plans
  FOR SELECT TO authenticated USING (
    academy_id = public.current_academy_id()
    AND public.is_academy_admin()
  );

DROP POLICY IF EXISTS "PDP read coach" ON public.player_development_plans;
CREATE POLICY "PDP read coach" ON public.player_development_plans
  FOR SELECT TO authenticated USING (
    academy_id = public.current_academy_id()
    AND public.is_academy_coach()
    AND (player_id = ANY (public.current_coach_player_ids()) OR created_by = auth.uid())
  );

-- Players see their own plan when the coach shared it with them;
-- parents see their children's plan when shared with them.
DROP POLICY IF EXISTS "PDP read player" ON public.player_development_plans;
CREATE POLICY "PDP read player" ON public.player_development_plans
  FOR SELECT TO authenticated USING (
    player_id = auth.uid()
    AND visibility IN ('player', 'parent')
  );

DROP POLICY IF EXISTS "PDP read parent" ON public.player_development_plans;
CREATE POLICY "PDP read parent" ON public.player_development_plans
  FOR SELECT TO authenticated USING (
    visibility IN ('parent')
    AND EXISTS (
      SELECT 1 FROM public.profiles child
      WHERE child.id = player_id AND child.guardian_id = auth.uid()
    )
  );

DROP POLICY IF EXISTS "PDP goals read" ON public.player_development_goals;
CREATE POLICY "PDP goals read" ON public.player_development_goals
  FOR SELECT TO authenticated USING (
    EXISTS (
      SELECT 1 FROM public.player_development_plans p
      WHERE p.id = plan_id
        AND (
          p.player_id = auth.uid()
          OR p.academy_id = public.current_academy_id()
        )
    )
  );

-- AI usage log: only admins read; server logs insertions for staff.
DROP POLICY IF EXISTS "AI usage read admin" ON public.ai_usage_log;
CREATE POLICY "AI usage read admin" ON public.ai_usage_log
  FOR SELECT TO authenticated USING (
    academy_id = public.current_academy_id()
    AND public.is_academy_admin()
  );

DROP POLICY IF EXISTS "AI usage insert staff" ON public.ai_usage_log;
CREATE POLICY "AI usage insert staff" ON public.ai_usage_log
  FOR INSERT TO authenticated WITH CHECK (
    academy_id = public.current_academy_id()
    AND public.is_academy_staff()
  );

-- ── 4. MUTATION RPCs (all writes go through these) ─────────

-- Save (create or edit) an AI training plan including its sections and
-- exercises. Editing is locked for approved/archived plans; a new version is
-- snapshotted on every change.
CREATE OR REPLACE FUNCTION public.save_ai_training_plan(p_plan JSONB)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_id UUID;
  v_team_id UUID;
  v_version INTEGER;
  v_created_by UUID;
  v_section JSONB;
  v_section_id UUID;
  v_exercise JSONB;
  v_can_edit TEXT;
  v_academy UUID;
BEGIN
  IF auth.uid() IS NULL OR public.is_academy_staff() IS NOT TRUE THEN
    RAISE EXCEPTION 'Only academy staff can save training plans' USING ERRCODE = '42501';
  END IF;
  IF p_plan IS NULL OR jsonb_typeof(p_plan) <> 'object' THEN
    RAISE EXCEPTION 'Plan payload must be an object';
  END IF;

  v_academy := public.current_academy_id();
  v_team_id := NULLIF(p_plan ->> 'team_id', '')::UUID;
  v_created_by := auth.uid();

  -- Team scoping: coaches may only attach plans to their own teams.
  IF public.is_academy_admin() IS NOT TRUE AND v_team_id IS NOT NULL
     AND v_team_id <> ALL (public.current_coach_team_ids()) THEN
    RAISE EXCEPTION 'You can only create plans for teams assigned to you';
  END IF;

  v_id := NULLIF(p_plan ->> 'id', '')::UUID;

  IF v_id IS NULL THEN
    -- ── CREATE ───────────────────────────────────────────────
    INSERT INTO public.ai_training_plans (
      academy_id, branch_id, team_id, session_id, sport_id, sport, title,
      main_objective, secondary_objectives, skill_focus, intensity_theme,
      session_duration_min, num_players, num_coaches, age_group, skill_level,
      gender, equipment, space, notes, status, created_by, updated_by
    ) VALUES (
      v_academy,
      NULLIF(p_plan ->> 'branch_id', '')::UUID,
      v_team_id,
      NULLIF(p_plan ->> 'session_id', '')::UUID,
      NULLIF(p_plan ->> 'sport_id', '')::UUID,
      NULLIF(p_plan ->> 'sport', ''),
      NULLIF(btrim(p_plan ->> 'title'), ''),
      NULLIF(p_plan ->> 'main_objective', ''),
      COALESCE(p_plan -> 'secondary_objectives', '[]'::JSONB),
      COALESCE(p_plan -> 'skill_focus', '[]'::JSONB),
      COALESCE(NULLIF(p_plan ->> 'intensity_theme', ''), 'moderate'),
      COALESCE((p_plan ->> 'session_duration_min')::INTEGER, 60),
      COALESCE((p_plan ->> 'num_players')::INTEGER, 0),
      COALESCE((p_plan ->> 'num_coaches')::INTEGER, 1),
      NULLIF(p_plan ->> 'age_group', ''),
      NULLIF(p_plan ->> 'skill_level', ''),
      NULLIF(p_plan ->> 'gender', ''),
      COALESCE(p_plan -> 'equipment', '[]'::JSONB),
      NULLIF(p_plan ->> 'space', ''),
      NULLIF(p_plan ->> 'notes', ''),
      'draft',
      v_created_by, v_created_by
    )
    RETURNING id INTO v_id;
    v_version := 1;
  ELSE
    -- ── EDIT ─────────────────────────────────────────────────
    SELECT status, version, created_by, academy_id INTO v_can_edit, v_version,
      v_created_by, v_academy
    FROM public.ai_training_plans WHERE id = v_id;
    IF v_can_edit IS NULL THEN
      RAISE EXCEPTION 'Plan not found';
    END IF;
    IF v_academy <> public.current_academy_id() THEN
      RAISE EXCEPTION 'Plan belongs to another academy' USING ERRCODE = '42501';
    END IF;
    -- Content is locked after approval; only status/navigation actions allowed.
    IF v_can_edit IN ('approved', 'archived') THEN
      RAISE EXCEPTION 'This plan is % and its content is locked', v_can_edit;
    END IF;
    IF public.is_academy_admin() IS NOT TRUE AND v_created_by <> auth.uid() THEN
      RAISE EXCEPTION 'Only the plan author or an admin can edit this plan' USING ERRCODE = '42501';
    END IF;

    UPDATE public.ai_training_plans SET
      branch_id = NULLIF(p_plan ->> 'branch_id', '')::UUID,
      team_id = NULLIF(p_plan ->> 'team_id', '')::UUID,
      session_id = NULLIF(p_plan ->> 'session_id', '')::UUID,
      sport_id = NULLIF(p_plan ->> 'sport_id', '')::UUID,
      sport = NULLIF(p_plan ->> 'sport', ''),
      title = NULLIF(btrim(p_plan ->> 'title'), ''),
      main_objective = NULLIF(p_plan ->> 'main_objective', ''),
      secondary_objectives = COALESCE(p_plan -> 'secondary_objectives', '[]'::JSONB),
      skill_focus = COALESCE(p_plan -> 'skill_focus', '[]'::JSONB),
      intensity_theme = COALESCE(NULLIF(p_plan ->> 'intensity_theme', ''), 'moderate'),
      session_duration_min = COALESCE((p_plan ->> 'session_duration_min')::INTEGER, 60),
      num_players = COALESCE((p_plan ->> 'num_players')::INTEGER, 0),
      num_coaches = COALESCE((p_plan ->> 'num_coaches')::INTEGER, 1),
      age_group = NULLIF(p_plan ->> 'age_group', ''),
      skill_level = NULLIF(p_plan ->> 'skill_level', ''),
      gender = NULLIF(p_plan ->> 'gender', ''),
      equipment = COALESCE(p_plan -> 'equipment', '[]'::JSONB),
      space = NULLIF(p_plan ->> 'space', ''),
      notes = NULLIF(p_plan ->> 'notes', ''),
      version = version + 1,
      updated_by = auth.uid(),
      updated_at = NOW()
    WHERE id = v_id;
    v_version := v_version + 1;

    -- Replace sections & exercises wholesale (child tables cascade on delete
    -- of the plan only, so we delete explicitly by ids).
    DELETE FROM public.ai_training_plan_sections WHERE plan_id = v_id;
  END IF;

  -- Insert sections & exercises.
  IF jsonb_typeof(p_plan -> 'sections') = 'array' THEN
    FOR v_section IN SELECT * FROM jsonb_array_elements(p_plan -> 'sections') LOOP
      INSERT INTO public.ai_training_plan_sections (
        plan_id, section_type, title, purpose, duration_min, skill_focus, order_index
      ) VALUES (
        v_id,
        COALESCE(NULLIF(v_section ->> 'section_type', ''), 'technical'),
        NULLIF(btrim(v_section ->> 'title'), ''),
        NULLIF(v_section ->> 'purpose', ''),
        COALESCE((v_section ->> 'duration_min')::INTEGER, 10),
        COALESCE(v_section -> 'skill_focus', '[]'::JSONB),
        COALESCE((v_section ->> 'order_index')::INTEGER, 0)
      )
      RETURNING id INTO v_section_id;

      IF jsonb_typeof(v_section -> 'exercises') = 'array' THEN
        FOR v_exercise IN SELECT * FROM jsonb_array_elements(v_section -> 'exercises') LOOP
          INSERT INTO public.training_exercises (
            section_id, name, purpose, duration_min, num_players, equipment,
            setup, instructions, coaching_points, difficulty, order_index,
            ai_generated
          ) VALUES (
            v_section_id,
            NULLIF(btrim(v_exercise ->> 'name'), ''),
            NULLIF(v_exercise ->> 'purpose', ''),
            COALESCE((v_exercise ->> 'duration_min')::INTEGER, 5),
            NULLIF(v_exercise ->> 'num_players', '')::INTEGER,
            COALESCE(v_exercise -> 'equipment', '[]'::JSONB),
            NULLIF(v_exercise ->> 'setup', ''),
            COALESCE(v_exercise -> 'instructions', '[]'::JSONB),
            COALESCE(v_exercise -> 'coaching_points', '[]'::JSONB),
            NULLIF(v_exercise ->> 'difficulty', ''),
            COALESCE((v_exercise ->> 'order_index')::INTEGER, 0),
            COALESCE((v_exercise ->> 'ai_generated')::BOOLEAN, FALSE)
          );
        END LOOP;
      END IF;
    END LOOP;
  END IF;

  -- Snapshot the version.
  INSERT INTO public.training_plan_versions (plan_id, version, editor_id, action, snapshot)
  VALUES (
    v_id,
    v_version,
    auth.uid(),
    CASE WHEN (p_plan -> 'sections') IS NOT NULL THEN 'edited' ELSE 'generated' END,
    coalesce(p_plan, '{}'::jsonb)
  );

  RETURN v_id;
END;
$$;
REVOKE ALL ON FUNCTION public.save_ai_training_plan(JSONB) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.save_ai_training_plan(JSONB) TO authenticated;

-- Submit a draft for review.
CREATE OR REPLACE FUNCTION public.submit_ai_training_plan(p_plan_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_status TEXT;
  v_creator UUID;
  v_academy UUID;
BEGIN
  IF auth.uid() IS NULL OR public.is_academy_staff() IS NOT TRUE THEN
    RAISE EXCEPTION 'Only academy staff can submit plans' USING ERRCODE = '42501';
  END IF;
  SELECT status, created_by, academy_id INTO v_status, v_creator, v_academy
    FROM public.ai_training_plans WHERE id = p_plan_id;
  IF v_status IS NULL THEN RAISE EXCEPTION 'Plan not found'; END IF;
  IF v_academy <> public.current_academy_id() THEN
    RAISE EXCEPTION 'Plan belongs to another academy' USING ERRCODE = '42501';
  END IF;
  IF public.is_academy_admin() IS NOT TRUE AND v_creator <> auth.uid() THEN
    RAISE EXCEPTION 'Only the plan author can submit it' USING ERRCODE = '42501';
  END IF;
  IF v_status NOT IN ('draft', 'rejected') THEN
    RAISE EXCEPTION 'Only draft or rejected plans can be submitted';
  END IF;

  UPDATE public.ai_training_plans
    SET status = 'submitted', updated_by = auth.uid(), updated_at = NOW(),
        version = version + 1
    WHERE id = p_plan_id;
  INSERT INTO public.training_plan_versions (plan_id, version, editor_id, action, snapshot)
    SELECT p_plan_id, version, auth.uid(), 'submitted', to_jsonb(p_plan_id)
    FROM public.ai_training_plans WHERE id = p_plan_id;
END;
$$;
REVOKE ALL ON FUNCTION public.submit_ai_training_plan(UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.submit_ai_training_plan(UUID) TO authenticated;

-- Approve or reject a submitted plan (owner/admins, or the creating coach for
-- small academies where the head coach is the plan author).
CREATE OR REPLACE FUNCTION public.decide_ai_training_plan(
  p_plan_id UUID,
  p_approved BOOLEAN,
  p_reason TEXT DEFAULT NULL
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_status TEXT;
  v_creator UUID;
  v_academy UUID;
BEGIN
  IF auth.uid() IS NULL OR public.is_academy_staff() IS NOT TRUE THEN
    RAISE EXCEPTION 'Only academy staff can review plans' USING ERRCODE = '42501';
  END IF;
  SELECT status, created_by, academy_id INTO v_status, v_creator, v_academy
    FROM public.ai_training_plans WHERE id = p_plan_id;
  IF v_status IS NULL THEN RAISE EXCEPTION 'Plan not found'; END IF;
  IF v_academy <> public.current_academy_id() THEN
    RAISE EXCEPTION 'Plan belongs to another academy' USING ERRCODE = '42501';
  END IF;
  IF v_status <> 'submitted' THEN
    RAISE EXCEPTION 'Only submitted plans can be approved or rejected';
  END IF;
  IF public.is_academy_admin() IS NOT TRUE AND v_creator <> auth.uid() THEN
    RAISE EXCEPTION 'Only the plan author or an academy owner can approve this plan' USING ERRCODE = '42501';
  END IF;

  IF p_approved THEN
    UPDATE public.ai_training_plans
      SET status = 'approved', approval_note = p_reason, approved_by = auth.uid(),
          approved_at = NOW(), updated_by = auth.uid(), updated_at = NOW(),
          version = version + 1
      WHERE id = p_plan_id;
    INSERT INTO public.training_plan_versions (plan_id, version, editor_id, action, snapshot)
      SELECT p_plan_id, version, auth.uid(), 'approved', jsonb_build_object('reason', p_reason)
      FROM public.ai_training_plans WHERE id = p_plan_id;

    INSERT INTO public.notifications (recipient_id, type, title, body, link)
    SELECT v_creator, 'ai_plan_approved', 'Training plan approved',
      'Your training plan has been approved', '/coach-ai/plans/' || p_plan_id;
  ELSE
    UPDATE public.ai_training_plans
      SET status = 'rejected', approval_note = p_reason, updated_by = auth.uid(),
          updated_at = NOW(), version = version + 1
      WHERE id = p_plan_id;
    INSERT INTO public.training_plan_versions (plan_id, version, editor_id, action, snapshot)
      SELECT p_plan_id, version, auth.uid(), 'rejected', jsonb_build_object('reason', p_reason)
      FROM public.ai_training_plans WHERE id = p_plan_id;

    INSERT INTO public.notifications (recipient_id, type, title, body, link)
    SELECT v_creator, 'ai_plan_rejected', 'Training plan needs revision',
      COALESCE(p_reason, 'The plan was rejected and needs revisions'), '/coach-ai/plans/' || p_plan_id;
  END IF;
END;
$$;
REVOKE ALL ON FUNCTION public.decide_ai_training_plan(UUID, BOOLEAN, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.decide_ai_training_plan(UUID, BOOLEAN, TEXT) TO authenticated;

-- Toggle favorite / template flags.
CREATE OR REPLACE FUNCTION public.toggle_ai_plan_flags(
  p_plan_id UUID,
  p_favorite BOOLEAN DEFAULT NULL,
  p_is_template BOOLEAN DEFAULT NULL,
  p_template_name TEXT DEFAULT NULL
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_row public.ai_training_plans%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM public.ai_training_plans WHERE id = p_plan_id;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'Plan not found'; END IF;
  IF v_row.academy_id <> public.current_academy_id() THEN
    RAISE EXCEPTION 'Plan belongs to another academy' USING ERRCODE = '42501';
  END IF;
  IF public.is_academy_admin() IS NOT TRUE AND v_row.created_by <> auth.uid() THEN
    RAISE EXCEPTION 'Only the plan author or an admin can update plan flags' USING ERRCODE = '42501';
  END IF;

  UPDATE public.ai_training_plans SET
    is_favorite = COALESCE(p_favorite, is_favorite),
    is_template = COALESCE(p_is_template, is_template),
    template_name = CASE WHEN p_is_template = TRUE
      THEN COALESCE(NULLIF(btrim(p_template_name), ''), v_row.template_name, v_row.title)
      ELSE template_name END,
    updated_at = NOW()
  WHERE id = p_plan_id;
END;
$$;
REVOKE ALL ON FUNCTION public.toggle_ai_plan_flags(UUID, BOOLEAN, BOOLEAN, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.toggle_ai_plan_flags(UUID, BOOLEAN, BOOLEAN, TEXT) TO authenticated;

-- Duplicate a plan (used to bootstrap a fresh editable copy from a template).
CREATE OR REPLACE FUNCTION public.duplicate_ai_training_plan(p_plan_id UUID)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_src public.ai_training_plans%ROWTYPE;
  v_new_id UUID;
  v_section RECORD;
  v_new_section_id UUID;
  v_exercise RECORD;
BEGIN
  IF auth.uid() IS NULL OR public.is_academy_staff() IS NOT TRUE THEN
    RAISE EXCEPTION 'Only academy staff can duplicate plans' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_src FROM public.ai_training_plans WHERE id = p_plan_id;
  IF v_src.id IS NULL THEN RAISE EXCEPTION 'Plan not found'; END IF;
  IF v_src.academy_id <> public.current_academy_id() THEN
    RAISE EXCEPTION 'Plan belongs to another academy' USING ERRCODE = '42501';
  END IF;
  IF public.is_academy_admin() IS NOT TRUE
     AND v_src.created_by <> auth.uid()
     AND v_src.team_id <> ALL (public.current_coach_team_ids())
     AND v_src.is_template IS NOT TRUE THEN
    RAISE EXCEPTION 'You cannot duplicate this plan' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.ai_training_plans (
    academy_id, branch_id, team_id, session_id, sport_id, sport, title,
    main_objective, secondary_objectives, skill_focus, intensity_theme,
    session_duration_min, num_players, num_coaches, age_group, skill_level,
    gender, equipment, space, notes, status, is_favorite, ai_provider, ai_model,
    ai_generation_id, ai_estimated_cost, created_by, updated_by
  ) VALUES (
    v_src.academy_id, v_src.branch_id, v_src.team_id, NULL, v_src.sport_id,
    v_src.sport, v_src.title || ' (copy)', v_src.main_objective,
    v_src.secondary_objectives, v_src.skill_focus, v_src.intensity_theme,
    v_src.session_duration_min, v_src.num_players, v_src.num_coaches,
    v_src.age_group, v_src.skill_level, v_src.gender, v_src.equipment,
    v_src.space, v_src.notes, 'draft', FALSE, v_src.ai_provider, v_src.ai_model,
    v_src.ai_generation_id, v_src.ai_estimated_cost, auth.uid(), auth.uid()
  ) RETURNING id INTO v_new_id;

  FOR v_section IN
    SELECT * FROM public.ai_training_plan_sections s WHERE s.plan_id = p_plan_id ORDER BY s.order_index, s.created_at
  LOOP
    INSERT INTO public.ai_training_plan_sections (
      plan_id, section_type, title, purpose, duration_min, skill_focus, order_index
    ) VALUES (
      v_new_id, v_section.section_type, v_section.title, v_section.purpose,
      v_section.duration_min, v_section.skill_focus, v_section.order_index
    ) RETURNING id INTO v_new_section_id;

    FOR v_exercise IN
      SELECT * FROM public.training_exercises e WHERE e.section_id = v_section.id ORDER BY e.order_index, e.created_at
    LOOP
      INSERT INTO public.training_exercises (
        section_id, name, purpose, duration_min, num_players, equipment, setup,
        instructions, coaching_points, difficulty, order_index, ai_generated
      ) VALUES (
        v_new_section_id, v_exercise.name, v_exercise.purpose, v_exercise.duration_min,
        v_exercise.num_players, v_exercise.equipment, v_exercise.setup,
        v_exercise.instructions, v_exercise.coaching_points, v_exercise.difficulty,
        v_exercise.order_index, v_exercise.ai_generated
      );
    END LOOP;
  END LOOP;

  INSERT INTO public.training_plan_versions (plan_id, version, editor_id, action, snapshot)
    SELECT v_new_id, 1, auth.uid(), 'created', to_jsonb(v_new_id);

  RETURN v_new_id;
END;
$$;
REVOKE ALL ON FUNCTION public.duplicate_ai_training_plan(UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.duplicate_ai_training_plan(UUID) TO authenticated;

-- Archive a plan (soft delete; never physical deletes).
CREATE OR REPLACE FUNCTION public.archive_ai_training_plan(p_plan_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_row public.ai_training_plans%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM public.ai_training_plans WHERE id = p_plan_id;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'Plan not found'; END IF;
  IF v_row.academy_id <> public.current_academy_id() THEN
    RAISE EXCEPTION 'Plan belongs to another academy' USING ERRCODE = '42501';
  END IF;
  IF public.is_academy_admin() IS NOT TRUE AND v_row.created_by <> auth.uid() THEN
    RAISE EXCEPTION 'Only the plan author or an admin can archive this plan' USING ERRCODE = '42501';
  END IF;

  UPDATE public.ai_training_plans
    SET status = 'archived', updated_at = NOW() WHERE id = p_plan_id;
  INSERT INTO public.training_plan_versions (plan_id, version, editor_id, action, snapshot)
    SELECT p_plan_id, version, auth.uid(), 'archived', '{}'::jsonb
    FROM public.ai_training_plans WHERE id = p_plan_id;
END;
$$;
REVOKE ALL ON FUNCTION public.archive_ai_training_plan(UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.archive_ai_training_plan(UUID) TO authenticated;

-- Restore a plan from an archived state as a fresh draft copy chain.
CREATE OR REPLACE FUNCTION public.restore_ai_training_plan(p_plan_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_row public.ai_training_plans%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM public.ai_training_plans WHERE id = p_plan_id;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'Plan not found'; END IF;
  IF v_row.academy_id <> public.current_academy_id() THEN
    RAISE EXCEPTION 'Plan belongs to another academy' USING ERRCODE = '42501';
  END IF;
  IF public.is_academy_admin() IS NOT TRUE AND v_row.created_by <> auth.uid() THEN
    RAISE EXCEPTION 'Only the plan author or an admin can restore this plan' USING ERRCODE = '42501';
  END IF;

  UPDATE public.ai_training_plans
    SET status = 'draft', updated_at = NOW() WHERE id = p_plan_id;
  INSERT INTO public.training_plan_versions (plan_id, version, editor_id, action, snapshot)
    SELECT p_plan_id, version, auth.uid(), 'restored', '{}'::jsonb
    FROM public.ai_training_plans WHERE id = p_plan_id;
END;
$$;
REVOKE ALL ON FUNCTION public.restore_ai_training_plan(UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.restore_ai_training_plan(UUID) TO authenticated;

-- Assign a plan to one or more training sessions.
CREATE OR REPLACE FUNCTION public.assign_ai_training_plan(
  p_plan_id UUID,
  p_session_ids UUID[],
  p_scheduled_at TIMESTAMPTZ DEFAULT NULL,
  p_notes TEXT DEFAULT NULL
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_row public.ai_training_plans%ROWTYPE;
  v_session_id UUID;
BEGIN
  IF auth.uid() IS NULL OR public.is_academy_staff() IS NOT TRUE THEN
    RAISE EXCEPTION 'Only academy staff can assign plans' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_row FROM public.ai_training_plans WHERE id = p_plan_id;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'Plan not found'; END IF;
  IF v_row.academy_id <> public.current_academy_id() THEN
    RAISE EXCEPTION 'Plan belongs to another academy' USING ERRCODE = '42501';
  END IF;

  FOREACH v_session_id IN ARRAY p_session_ids LOOP
    INSERT INTO public.training_plan_assignments (plan_id, session_id, scheduled_at, notes, assigned_by)
    VALUES (p_plan_id, v_session_id, p_scheduled_at, p_notes, auth.uid())
    ON CONFLICT (plan_id, session_id) DO NOTHING;
  END LOOP;
END;
$$;
REVOKE ALL ON FUNCTION public.assign_ai_training_plan(UUID, UUID[], TIMESTAMPTZ, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.assign_ai_training_plan(UUID, UUID[], TIMESTAMPTZ, TEXT) TO authenticated;

-- Unassign a plan from a training session.
CREATE OR REPLACE FUNCTION public.unassign_ai_training_plan(p_plan_id UUID, p_session_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_row public.ai_training_plans%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM public.ai_training_plans WHERE id = p_plan_id;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'Plan not found'; END IF;
  IF v_row.academy_id <> public.current_academy_id() THEN
    RAISE EXCEPTION 'Plan belongs to another academy' USING ERRCODE = '42501';
  END IF;
  DELETE FROM public.training_plan_assignments a
    WHERE a.plan_id = p_plan_id AND a.session_id = p_session_id;
END;
$$;
REVOKE ALL ON FUNCTION public.unassign_ai_training_plan(UUID, UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.unassign_ai_training_plan(UUID, UUID) TO authenticated;

-- Save (upsert) a post-session report.
CREATE OR REPLACE FUNCTION public.save_post_session_report(p_report JSONB)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_id UUID;
  v_plan_id UUID;
  v_academy UUID;
BEGIN
  IF auth.uid() IS NULL OR public.is_academy_staff() IS NOT TRUE THEN
    RAISE EXCEPTION 'Only academy staff can save reports' USING ERRCODE = '42501';
  END IF;
  IF p_report IS NULL OR jsonb_typeof(p_report) <> 'object' THEN
    RAISE EXCEPTION 'Report payload must be an object';
  END IF;

  v_plan_id := NULLIF(p_report ->> 'plan_id', '')::UUID;
  IF v_plan_id IS NOT NULL THEN
    SELECT academy_id INTO v_academy FROM public.ai_training_plans WHERE id = v_plan_id;
    IF v_academy IS NOT NULL AND v_academy <> public.current_academy_id() THEN
      RAISE EXCEPTION 'Plan belongs to another academy' USING ERRCODE = '42501';
    END IF;
  END IF;

  v_id := NULLIF(p_report ->> 'id', '')::UUID;

  IF v_id IS NULL THEN
    INSERT INTO public.post_session_reports (
      academy_id, plan_id, session_id, team_id, coach_id, completed,
      actual_duration_min, exercises_performance, performance_rating,
      intensity_rating, engagement_rating, skills_improved, skills_need_work,
      injuries, notes, player_notes, created_by
    ) VALUES (
      public.current_academy_id(),
      v_plan_id,
      NULLIF(p_report ->> 'session_id', '')::UUID,
      NULLIF(p_report ->> 'team_id', '')::UUID,
      COALESCE(NULLIF(p_report ->> 'coach_id', '')::UUID, auth.uid()),
      COALESCE((p_report ->> 'completed')::BOOLEAN, TRUE),
      NULLIF(p_report ->> 'actual_duration_min', '')::INTEGER,
      COALESCE(p_report -> 'exercises_performance', '[]'::JSONB),
      NULLIF(p_report ->> 'performance_rating', '')::INTEGER,
      NULLIF(p_report ->> 'intensity_rating', '')::INTEGER,
      NULLIF(p_report ->> 'engagement_rating', '')::INTEGER,
      COALESCE(p_report -> 'skills_improved', '[]'::JSONB),
      COALESCE(p_report -> 'skills_need_work', '[]'::JSONB),
      COALESCE(p_report -> 'injuries', '[]'::JSONB),
      NULLIF(p_report ->> 'notes', ''),
      COALESCE(p_report -> 'player_notes', '[]'::JSONB),
      auth.uid()
    )
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.post_session_reports SET
      plan_id = v_plan_id,
      session_id = NULLIF(p_report ->> 'session_id', '')::UUID,
      team_id = NULLIF(p_report ->> 'team_id', '')::UUID,
      coach_id = COALESCE(NULLIF(p_report ->> 'coach_id', '')::UUID, auth.uid()),
      completed = COALESCE((p_report ->> 'completed')::BOOLEAN, TRUE),
      actual_duration_min = NULLIF(p_report ->> 'actual_duration_min', '')::INTEGER,
      exercises_performance = COALESCE(p_report -> 'exercises_performance', '[]'::JSONB),
      performance_rating = NULLIF(p_report ->> 'performance_rating', '')::INTEGER,
      intensity_rating = NULLIF(p_report ->> 'intensity_rating', '')::INTEGER,
      engagement_rating = NULLIF(p_report ->> 'engagement_rating', '')::INTEGER,
      skills_improved = COALESCE(p_report -> 'skills_improved', '[]'::JSONB),
      skills_need_work = COALESCE(p_report -> 'skills_need_work', '[]'::JSONB),
      injuries = COALESCE(p_report -> 'injuries', '[]'::JSONB),
      notes = NULLIF(p_report ->> 'notes', ''),
      player_notes = COALESCE(p_report -> 'player_notes', '[]'::JSONB),
      updated_at = NOW()
    WHERE id = v_id
      AND academy_id = public.current_academy_id();
    IF NOT FOUND THEN RAISE EXCEPTION 'Report not found or belongs to another academy'; END IF;
  END IF;

  RETURN v_id;
END;
$$;
REVOKE ALL ON FUNCTION public.save_post_session_report(JSONB) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.save_post_session_report(JSONB) TO authenticated;

-- Save (upsert) a player development plan with its goals.
CREATE OR REPLACE FUNCTION public.save_player_development_plan(p_plan JSONB)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_id UUID;
  v_player uuid;
  v_goal JSONB;
  v_academy UUID;
  v_is_own_player BOOLEAN;
BEGIN
  IF auth.uid() IS NULL OR public.is_academy_staff() IS NOT TRUE THEN
    RAISE EXCEPTION 'Only academy staff can manage development plans' USING ERRCODE = '42501';
  END IF;
  IF p_plan IS NULL OR jsonb_typeof(p_plan) <> 'object' THEN
    RAISE EXCEPTION 'Payload must be an object';
  END IF;

  v_id := NULLIF(p_plan ->> 'id', '')::UUID;
  v_player := NULLIF(p_plan ->> 'player_id', '')::UUID;
  IF v_player IS NULL THEN RAISE EXCEPTION 'player_id is required'; END IF;

  IF public.is_academy_admin() IS NOT TRUE THEN
    SELECT EXISTS (
      SELECT 1 FROM public.team_members tm
      WHERE tm.member_id = v_player
        AND tm.team_id = ANY (public.current_coach_team_ids())
    ) INTO v_is_own_player;
    IF COALESCE(v_is_own_player, FALSE) IS NOT TRUE THEN
      RAISE EXCEPTION 'You can only create development plans for players on your teams' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF v_id IS NULL THEN
    INSERT INTO public.player_development_plans (
      academy_id, player_id, coach_id, sport, position, strengths,
      areas_to_improve, short_term_goals, long_term_goals, recommended_drills,
      weekly_focus, progress_checkpoints, review_date, visibility, private_notes,
      created_by
    ) VALUES (
      public.current_academy_id(), v_player,
      COALESCE(NULLIF(p_plan ->> 'coach_id', '')::UUID, auth.uid()),
      NULLIF(p_plan ->> 'sport', ''), NULLIF(p_plan ->> 'position', ''),
      COALESCE(p_plan -> 'strengths', '[]'::JSONB),
      COALESCE(p_plan -> 'areas_to_improve', '[]'::JSONB),
      COALESCE(p_plan -> 'short_term_goals', '[]'::JSONB),
      COALESCE(p_plan -> 'long_term_goals', '[]'::JSONB),
      COALESCE(p_plan -> 'recommended_drills', '[]'::JSONB),
      NULLIF(p_plan ->> 'weekly_focus', ''),
      COALESCE(p_plan -> 'progress_checkpoints', '[]'::JSONB),
      NULLIF(p_plan ->> 'review_date', '')::DATE,
      COALESCE(NULLIF(p_plan ->> 'visibility', ''), 'coach'),
      NULLIF(p_plan ->> 'private_notes', ''),
      auth.uid()
    )
    RETURNING id INTO v_id;
  ELSE
    SELECT academy_id, player_id INTO v_academy, v_player
      FROM public.player_development_plans WHERE id = v_id;
    IF v_academy IS NULL THEN RAISE EXCEPTION 'Plan not found'; END IF;
    IF v_academy <> public.current_academy_id() THEN
      RAISE EXCEPTION 'Plan belongs to another academy' USING ERRCODE = '42501';
    END IF;
    UPDATE public.player_development_plans SET
      player_id = v_player,
      coach_id = COALESCE(NULLIF(p_plan ->> 'coach_id', '')::UUID, coach_id),
      sport = NULLIF(p_plan ->> 'sport', ''),
      position = NULLIF(p_plan ->> 'position', ''),
      strengths = COALESCE(p_plan -> 'strengths', strengths),
      areas_to_improve = COALESCE(p_plan -> 'areas_to_improve', areas_to_improve),
      short_term_goals = COALESCE(p_plan -> 'short_term_goals', short_term_goals),
      long_term_goals = COALESCE(p_plan -> 'long_term_goals', long_term_goals),
      recommended_drills = COALESCE(p_plan -> 'recommended_drills', recommended_drills),
      weekly_focus = NULLIF(p_plan ->> 'weekly_focus', ''),
      progress_checkpoints = COALESCE(p_plan -> 'progress_checkpoints', progress_checkpoints),
      review_date = NULLIF(p_plan ->> 'review_date', '')::DATE,
      visibility = COALESCE(NULLIF(p_plan ->> 'visibility', ''), visibility),
      private_notes = NULLIF(p_plan ->> 'private_notes', ''),
      updated_at = NOW()
    WHERE id = v_id;
  END IF;

  -- Replace goals wholesale.
  DELETE FROM public.player_development_goals WHERE plan_id = v_id;
  IF jsonb_typeof(p_plan -> 'goals') = 'array' THEN
    FOR v_goal IN SELECT * FROM jsonb_array_elements(p_plan -> 'goals') LOOP
      INSERT INTO public.player_development_goals (
        plan_id, title, goal_type, target_date, progress, achieved, notes, order_index
      ) VALUES (
        v_id,
        NULLIF(btrim(v_goal ->> 'title'), ''),
        COALESCE(NULLIF(v_goal ->> 'goal_type', ''), 'short_term'),
        NULLIF(v_goal ->> 'target_date', '')::DATE,
        COALESCE((v_goal ->> 'progress')::INTEGER, 0),
        COALESCE((v_goal ->> 'achieved')::BOOLEAN, FALSE),
        NULLIF(v_goal ->> 'notes', ''),
        COALESCE((v_goal ->> 'order_index')::INTEGER, 0)
      );
    END LOOP;
  END IF;

  RETURN v_id;
END;
$$;
REVOKE ALL ON FUNCTION public.save_player_development_plan(JSONB) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.save_player_development_plan(JSONB) TO authenticated;

-- Approve or archive a development plan.
CREATE OR REPLACE FUNCTION public.decide_player_development_plan(
  p_plan_id UUID,
  p_approved BOOLEAN DEFAULT TRUE
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_row public.player_development_plans%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM public.player_development_plans WHERE id = p_plan_id;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'Plan not found'; END IF;
  IF v_row.academy_id <> public.current_academy_id() THEN
    RAISE EXCEPTION 'Plan belongs to another academy' USING ERRCODE = '42501';
  END IF;
  IF public.is_academy_admin() IS NOT TRUE AND v_row.created_by <> auth.uid() THEN
    RAISE EXCEPTION 'Only the plan author or an admin can finalize this plan' USING ERRCODE = '42501';
  END IF;

  IF p_approved THEN
    UPDATE public.player_development_plans
      SET status = 'approved', approved_by = auth.uid(), approved_at = NOW(),
          updated_at = NOW()
      WHERE id = p_plan_id;
  ELSE
    UPDATE public.player_development_plans
      SET status = 'archived', updated_at = NOW()
      WHERE id = p_plan_id;
  END IF;
END;
$$;
REVOKE ALL ON FUNCTION public.decide_player_development_plan(UUID, BOOLEAN) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.decide_player_development_plan(UUID, BOOLEAN) TO authenticated;